int read_7z_substream_info(struct archive_read *a, struct _7z_substream_info *ss, struct _7z_folder *f, size_t numFolders) {
  size_t i, totalUnpackStreams = 0;
  int ret = -1;

  ss->numFolders = numFolders;
  ss->folders = f;
  ss->num_unpack_streams = 0;
  ss->unpack_sizes = NULL;
  ss->digests = NULL;

  for (i = 0; i < numFolders; i++) {
    if (f[i].num_unpack_streams == 0)
      return -1;
    totalUnpackStreams += f[i].num_unpack_streams;
  }

  ss->num_unpack_streams = totalUnpackStreams;
  ss->unpack_sizes = (uint64_t *)malloc(totalUnpackStreams * sizeof(uint64_t));
  ss->digests = (uint32_t *)malloc(totalUnpackStreams * sizeof(uint32_t));

  if (ss->unpack_sizes == NULL || ss->digests == NULL) {
    free(ss->unpack_sizes);
    free(ss->digests);
    return -1;
  }

  totalUnpackStreams = 0;
  for (i = 0; i < numFolders; i++) {
    size_t j;
    for (j = 0; j < f[i].num_unpack_streams; j++) {
      if (archive_read_has_eof(a))
        goto fail;
      if (archive_read_data(a, &ss->unpack_sizes[totalUnpackStreams], sizeof(uint64_t)) != sizeof(uint64_t))
        goto fail;
      if (archive_read_data(a, &ss->digests[totalUnpackStreams], sizeof(uint32_t)) != sizeof(uint32_t))
        goto fail;
      totalUnpackStreams++;
    }
  }

  {
    uint8_t type;
    if (archive_read_has_eof(a))
      goto fail;
    if (archive_read_data(a, &type, sizeof(uint8_t)) != sizeof(uint8_t))
      goto fail;
    if (type != kEnd)
      goto fail;
  }

  ret = 0;
fail:
  if (ret != 0) {
    free(ss->unpack_sizes);
    free(ss->digests);
    ss->unpack_sizes = NULL;
    ss->digests = NULL;
    ss->num_unpack_streams = 0;
  }
  return ret;
}

int _7z_read_substream_info(struct archive_read *a, struct _7z_substream_info *ss, struct _7z_folder *f, size_t numFolders) {
  int ret;
  size_t i;
  struct _7z_folder *folder;

  ss->numFolders = numFolders;
  ss->folder = f;
  ss->num_unpack_streams = 0;
  ss->unpack_sizes = NULL;
  ss->digests = NULL;

  for (i = 0; i < numFolders; ++i) {
    folder = &f[i];
    if (folder->num_unpack_streams > ss->num_unpack_streams)
      ss->num_unpack_streams = folder->num_unpack_streams;
  }

  ss->unpack_sizes = (size_t *)malloc(ss->num_unpack_streams * sizeof(size_t));
  if (ss->unpack_sizes == NULL) {
    archive_set_error(&a->archive, ENOMEM, "Out of memory");
    return (-1);
  }

  ss->digests = (unsigned int *)malloc(ss->num_unpack_streams * sizeof(unsigned int));
  if (ss->digests == NULL) {
    archive_set_error(&a->archive, ENOMEM, "Out of memory");
    free(ss->unpack_sizes);
    return (-1);
  }

  for (i = 0; i < ss->num_unpack_streams; ++i) {
    ret = _7z_read_value(a, &ss->unpack_sizes[i], sizeof(size_t));
    if (ret != 0)
      return (-1);
  }

  for (i = 0; i < ss->num_unpack_streams; ++i) {
    ret = _7z_read_value(a, &ss->digests[i], sizeof(unsigned int));
    if (ret != 0)
      return (-1);
  }

  ret = _7z_read_type(a, NULL, 0);
  if (ret != kEnd)
    return (-1);

  return (0);
}

int read_7z_substream_info(struct archive_read *a, struct _7z_substream_info *ss, struct _7z_folder *f, size_t numFolders) {
    size_t i;
    int r;

    ss->numFolders = numFolders;
    ss->num_unpack_streams = 0;
    ss->unpack_sizes = NULL;
    ss->unpack_digests = NULL;

    for (i = 0; i < numFolders; i++) {
        r = read_uint64(a, &ss->num_unpack_streams);
        if (r != 0)
            return (-1);
    }

    ss->unpack_sizes = (uint64_t *)malloc(ss->num_unpack_streams * sizeof(uint64_t));
    if (ss->unpack_sizes == NULL)
        return (-1);

    for (i = 0; i < ss->num_unpack_streams; i++) {
        r = read_uint64(a, &ss->unpack_sizes[i]);
        if (r != 0) {
            free(ss->unpack_sizes);
            return (-1);
        }
    }

    r = read_byte(a, &ss->digests_present);
    if (r != 0) {
        free(ss->unpack_sizes);
        return (-1);
    }

    if (ss->digests_present) {
        ss->unpack_digests = (uint32_t *)malloc(ss->num_unpack_streams * sizeof(uint32_t));
        if (ss->unpack_digests == NULL) {
            free(ss->unpack_sizes);
            return (-1);
        }

        for (i = 0; i < ss->num_unpack_streams; i++) {
            r = read_uint32(a, &ss->unpack_digests[i]);
            if (r != 0) {
                free(ss->unpack_sizes);
                free(ss->unpack_digests);
                return (-1);
            }
        }
    }

    r = read_byte(a, &ss->final_type);
    if (r != 0 || ss->final_type != kEnd) {
        if (ss->digests_present)
            free(ss->unpack_digests);
        free(ss->unpack_sizes);
        return (-1);
    }

    return (0);
}

int read_substream_info(struct archive_read *a, struct _7z_substream_info *ss, struct _7z_folder *f, size_t numFolders) {
  int i, ret = 0;
  size_t numUnpackStreams = 0;

  ss->numFolders = numFolders;
  ss->folders = f;
  ss->digests = NULL;
  ss->unpSize = NULL;

  if (numFolders == 0)
    return (0);

  for (i = 0; i < (int)numFolders; ++i) {
    if (f[i].num_unpack_streams == 0) {
      archive_set_error(&a->archive, ARCHIVE_ERRNO_MISC, "Invalid number of unpack streams");
      return (-1);
    }
    numUnpackStreams += f[i].num_unpack_streams;
  }

  ss->unpSize = (uint64_t *)malloc(numUnpackStreams * sizeof(uint64_t));
  if (ss->unpSize == NULL) {
    archive_set_error(&a->archive, ENOMEM, "Out of memory");
    return (-1);
  }

  ss->digests = (uint32_t *)malloc(numUnpackStreams * sizeof(uint32_t));
  if (ss->digests == NULL) {
    free(ss->unpSize);
    archive_set_error(&a->archive, ENOMEM, "Out of memory");
    return (-1);
  }

  for (i = 0; i < (int)numFolders; ++i) {
    int j;

    for (j = 0; j < (int)f[i].num_unpack_streams; ++j) {
      if (archive_read(a) != ARCHIVE_OK) {
        ret = -1;
        goto cleanup;
      }

      ss->unpSize[i * f[i].num_unpack_streams + j] = archive_read(a);

      if (archive_read(a) != ARCHIVE_OK) {
        ret = -1;
        goto cleanup;
      }

      ss->digests[i * f[i].num_unpack_streams + j] = archive_read(a);
    }
  }

  if (ret != -1 && archive_read(a) != ARCHIVE_OK) {
    ret = -1;
  }

cleanup:
  if (ret == -1) {
    free(ss->unpSize);
    ss->unpSize = NULL;
    free(ss->digests);
    ss->digests = NULL;
  }

  if (ret != -1 && archive_read(a) != 0) {
    archive_set_error(&a->archive, ARCHIVE_ERRNO_MISC, "Unexpected end of archive");
    ret = -1;
  }

  return (ret);
}

int _7z_read_substream_info(struct archive_read *a, struct _7z_substream_info *ss,
                            struct _7z_folder *f, size_t numFolders) {
  int r;
  size_t i, j, numUnpackStreams = 0;

  for (i = 0; i < numFolders; ++i)
    numUnpackStreams += f[i].numUnpackStreams;

  ss->numFolders = numFolders;
  ss->folderStarts = (size_t *)malloc(sizeof(size_t) * numFolders);
  if (ss->folderStarts == NULL) {
    archive_set_error(&a->archive, ENOMEM, "Out of memory.");
    return (-1);
  }

  for (i = 0; i < numFolders; ++i) {
    ss->folderStarts[i] = f[i].folderStart;
    r = _7z_inflate_folder(a, f + i, ss->folderStarts[i], numUnpackStreams);
    if (r != 0)
      return (-1);
  }

  ss->unpackSizes = (uint64_t *)malloc(sizeof(uint64_t) * numUnpackStreams);
  if (ss->unpackSizes == NULL) {
    archive_set_error(&a->archive, ENOMEM, "Out of memory.");
    return (-1);
  }

  for (i = 0; i < numFolders; ++i)
    for (j = 0; j < f[i].numUnpackStreams; ++j)
      ss->unpackSizes[f[i].unpackStreamStart + j] = f[i].unpackSizes[j];

  return (0);
}
